        showAlert(`총 ${auditedItems.length}건의 실사를 일괄 전송하시겠습니까?`, async () => {
            setIsSaving(true);
            let successCount = 0;
            try {
                for (const item of auditedItems) {
                    const params = { Barcode: item.barcode, RealQty: item.auditQty };
