                            onChange={(e) => setApplyMode(e.target.value as 'immediate' | 'batch')}
                            className={`appearance-none pl-3 pr-8 py-2 rounded-lg text-xs font-bold border focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-colors cursor-pointer ${
                                applyMode === 'immediate' 
                                    ? 'bg-rose-50 border-rose-200 text-rose-700' 
                                    : 'bg-indigo-50 border-indigo-200 text-indigo-700'
                            }`}
