                                    </div>
                                    <div className={`p-1.5 rounded-lg border ${item.diff === 0 ? 'bg-gray-50 border-gray-100' : (item.diff > 0 ? 'bg-emerald-50 border-emerald-100' : 'bg-rose-50 border-rose-100')}`}>
