import React, { useState, useEffect, useMemo } from 'react';
import { useDataActions, useAlert, useModals } from '../context/AppContext';
import { Order } from '../types';
import { listenToOrderChangesByDateRange } from '../services/dbService';
import { exportToSMS, exportToXLS, exportReturnToPDF } from '../services/dataService';
import {
    SearchIcon, CheckCircleIcon,
    MoreVerticalIcon, SpinnerIcon, TrashIcon,
    SmsIcon, XlsIcon, ReturnBoxIcon, UndoIcon
} from '../components/Icons';
import DeliveryTypeModal from '../components/DeliveryTypeModal';

const OrderHistoryPage: React.FC<{ isActive: boolean }> = ({ isActive }) => {
    const { updateOrderStatus, deleteOrder } = useDataActions();
    const { showAlert, showToast } = useAlert();
    const { openDetailModal } = useModals();

    const [orders, setOrders] = useState<Order[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [startDate, setStartDate] = useState(() => {
        const d = new Date();
        d.setDate(d.getDate() - 7);
        return d.toISOString().slice(0, 10);
    });
    const [endDate, setEndDate] = useState(() => new Date().toISOString().slice(0, 10));
    const [searchTerm, setSearchTerm] = useState('');

    const [menuOpenId, setMenuOpenId] = useState<number | null>(null);
    const [selectedOrderForDelivery, setSelectedOrderForDelivery] = useState<Order | null>(null);

    useEffect(() => {
        if (!isActive) return;

        setIsLoading(true);
        setOrders([]);

        const unsubscribe = listenToOrderChangesByDateRange(
            new Date(endDate),
            {
                onAdd: (order) => setOrders(prev => {
                    if (prev.find(o => o.id === order.id)) return prev;
                    return [...prev, order].sort((a, b) => b.id - a.id);
                }),
                onChange: (order) => setOrders(prev => prev.map(o => o.id === order.id ? order : o).sort((a, b) => b.id - a.id)),
                onRemove: (order) => setOrders(prev => prev.filter(o => o.id !== order.id))
            },
            new Date(startDate)
        );

        setIsLoading(false);
        return () => unsubscribe();
    }, [isActive, startDate, endDate]);

    const filteredOrders = useMemo(() => {
        if (!searchTerm) return orders;
        const lower = searchTerm.toLowerCase();
        return orders.filter(o => o.customer.name.toLowerCase().includes(lower));
    }, [orders, searchTerm]);

    const handleMenuAction = async (action: string, order: Order) => {
        setMenuOpenId(null);

        try {
            if (action === 'delete') {
                showAlert('정말 삭제하시겠습니까?', async () => {
                    await deleteOrder(order.id);
                    showToast('삭제되었습니다.', 'success');
                }, '삭제', 'bg-rose-500');
            } else if (action === 'undo') {
                showAlert('완료 상태를 취소하시겠습니까?', async () => {
                    await updateOrderStatus(order.id, null);
                    showToast('미완료 상태로 변경되었습니다.', 'success');
                });
            } else if (action === 'sms') {
                const text = exportToSMS(order);
                if (navigator.share) {
                    await navigator.share({ title: `발주서_${order.customer.name}`, text: text });
                } else {
                    await navigator.clipboard.writeText(text);
                    showToast('클립보드에 복사되었습니다. 문자로 붙여넣기 하세요.');
                }
                await updateOrderStatus(order.id, { type: 'sms', timestamp: new Date().toISOString() });
            } else if (action === 'xls') {
                setSelectedOrderForDelivery(order);
            } else if (action === 'pdf') {
                 try {
                    const { blobUrl } = await exportReturnToPDF(order);
                    if (blobUrl) {
                        const link = document.createElement('a');
                        link.href = blobUrl;
                        link.download = `반품서_${order.customer.name}.pdf`;
                        link.click();
                        URL.revokeObjectURL(blobUrl);
                    }
                    await updateOrderStatus(order.id, { type: 'return', timestamp: new Date().toISOString() });
                } catch(e: any) {
                    showAlert(e.message);
                }
            }
        } catch (e: any) {
            showAlert(`오류 발생: ${e.message}`);
        }
    };

    const handleDeliveryConfirm = async (type: '일반배송' | '택배배송') => {
        if (!selectedOrderForDelivery) return;
        try {
            await exportToXLS(selectedOrderForDelivery, type);
            await updateOrderStatus(selectedOrderForDelivery.id, { type: 'xls', timestamp: new Date().toISOString() });
            showToast('엑셀 파일이 생성되었습니다.', 'success');
        } catch (e: any) {
            showAlert(e.message);
        } finally {
            setSelectedOrderForDelivery(null);
        }
    };

    return (
        <div className="h-full flex flex-col bg-gray-50">
            {/* Header / Filter */}
            <div className="p-3 bg-white border-b border-gray-200 shadow-sm z-10 flex-shrink-0 space-y-3">
                <div className="flex gap-2 items-center">
                    <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="flex-1 h-10 border border-gray-300 rounded-lg px-2 text-sm font-bold text-gray-700 bg-white shadow-sm outline-none focus:ring-2 focus:ring-blue-500" />
                    <span className="text-gray-400 font-bold">~</span>
                    <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="flex-1 h-10 border border-gray-300 rounded-lg px-2 text-sm font-bold text-gray-700 bg-white shadow-sm outline-none focus:ring-2 focus:ring-blue-500" />
                </div>
                <div className="relative">
                    <input 
                        type="text" 
                        value={searchTerm} 
                        onChange={e => setSearchTerm(e.target.value)} 
                        placeholder="거래처명 검색" 
                        className="w-full h-10 pl-10 pr-4 border border-gray-300 rounded-lg text-sm font-bold bg-white focus:ring-2 focus:ring-blue-500 outline-none"
                    />
                    <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                </div>
            </div>

            {/* List */}
            <div className="flex-grow overflow-y-auto p-2" onClick={() => setMenuOpenId(null)}>
                {isLoading ? (
                    <div className="flex items-center justify-center h-40"><SpinnerIcon className="w-8 h-8 text-blue-500 animate-spin" /></div>
                ) : filteredOrders.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-64 text-gray-400">
                        <p className="font-bold">주문 내역이 없습니다.</p>
                        <p className="text-sm">기간을 변경하거나 검색어를 확인하세요.</p>
                    </div>
                ) : (
                    <div className="space-y-3 pb-20">
                        {filteredOrders.map(order => {
                            const isCompleted = !!order.completedAt;
                            const isMenuOpen = menuOpenId === order.id;

                            return (
                                <div key={order.id} className={`bg-white rounded-xl border border-gray-200 shadow-sm relative transition-all ${isCompleted ? 'bg-gray-50' : ''}`}>
                                    <div className="p-3" onClick={() => openDetailModal(order)}>
                                        <div className="flex justify-between items-start mb-2">
                                            <div className="flex items-center gap-2">
                                                {isCompleted ? <CheckCircleIcon className="w-5 h-5 text-green-500" /> : <div className="w-5 h-5 rounded-full border-2 border-gray-300" />}
                                                <h3 className={`font-bold text-base ${isCompleted ? 'text-gray-500' : 'text-gray-800'}`}>{order.customer.name}</h3>
                                            </div>
                                            <span className="text-xs font-mono text-gray-400">{new Date(order.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                        </div>
                                        <div className="flex justify-between items-end pl-7">
                                            <div className="text-sm text-gray-600">
                                                <span className="font-bold text-gray-800">{order.itemCount}</span> 품목
                                            </div>
                                            <div className="text-right">
                                                <p className="text-lg font-black text-indigo-600">{order.total.toLocaleString()}<span className="text-xs font-normal text-gray-500 ml-0.5">원</span></p>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="absolute top-2 right-2">
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); setMenuOpenId(isMenuOpen ? null : order.id); }} 
                                            className="p-1.5 text-gray-400 hover:bg-gray-100 rounded-full transition-colors"
                                        >
                                            <MoreVerticalIcon className="w-5 h-5" />
                                        </button>

                                        {isMenuOpen && (
                                            <div className="absolute right-0 top-full mt-1 w-48 bg-white rounded-xl shadow-xl border border-gray-200 z-50 overflow-hidden animate-fade-in-up">
                                                {isCompleted ? (
                                                    <button
                                                        onClick={(e) => { e.stopPropagation(); handleMenuAction('undo', order); }}
                                                        className="w-full text-left px-4 py-3 text-sm font-medium text-gray-700 flex items-center gap-3 hover:bg-gray-50 active:bg-gray-100"
                                                    >
                                                        <UndoIcon className="w-4 h-4 text-gray-400" />
                                                        완료 취소
                                                    </button>
                                                ) : (
                                                    <>
                                                        <button
                                                            onClick={(e) => { e.stopPropagation(); handleMenuAction('sms', order); }}
                                                            className="w-full text-left px-4 py-3 text-sm font-medium text-gray-700 flex items-center gap-3 hover:bg-gray-50 active:bg-gray-100 border-b border-gray-50"
                                                        >
                                                            <SmsIcon className="w-4 h-4 text-green-500" />
                                                            SMS 내보내기
                                                        </button>
                                                        <button
                                                            onClick={(e) => { e.stopPropagation(); handleMenuAction('xls', order); }}
                                                            className="w-full text-left px-4 py-3 text-sm font-medium text-gray-700 flex items-center gap-3 hover:bg-gray-50 active:bg-gray-100 border-b border-gray-50"
                                                        >
                                                            <XlsIcon className="w-4 h-4 text-blue-500" />
                                                            XLS 내보내기
                                                        </button>
                                                        <button
                                                            onClick={(e) => { e.stopPropagation(); handleMenuAction('pdf', order); }}
                                                            className="w-full text-left px-4 py-3 text-sm font-medium text-gray-700 flex items-center gap-3 hover:bg-gray-50 active:bg-gray-100"
                                                        >
                                                            <ReturnBoxIcon className="w-4 h-4 text-gray-400" />
                                                            반품서 PDF
                                                        </button>
                                                    </>
                                                )}
                                                <div className="border-t border-gray-100">
                                                    <button
                                                        onClick={(e) => { e.stopPropagation(); handleMenuAction('delete', order); }}
                                                        className="w-full text-left px-4 py-3 text-sm font-bold text-rose-600 flex items-center gap-3 hover:bg-rose-50 active:bg-rose-100"
                                                    >
                                                        <TrashIcon className="w-4 h-4" />
                                                        삭제
                                                    </button>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>

            <DeliveryTypeModal 
                isOpen={!!selectedOrderForDelivery} 
                onClose={() => setSelectedOrderForDelivery(null)}
                onConfirm={handleDeliveryConfirm}
            />
        </div>
    );
};

