} from '../components/Icons';
import DeliveryTypeModal from '../components/DeliveryTypeModal';

interface OrderHistoryPageProps {
    isActive: boolean;
}

const OrderHistoryPage: React.FC<OrderHistoryPageProps> = ({ isActive }) => {
    const { updateOrderStatus, deleteOrder } = useDataActions();
    const { showAlert, showToast } = useAlert();
    const { openDetailModal } = useModals();

    const [startDate, setStartDate] = useState(() => {
        const d = new Date();
        d.setDate(d.getDate() - 6); // Last 7 days including today
        return d.toISOString().slice(0, 10);
    });
    const [endDate, setEndDate] = useState(() => new Date().toISOString().slice(0, 10));
    const [searchTerm, setSearchTerm] = useState('');

    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(false);

    const [activeMenuId, setActiveMenuId] = useState<number | null>(null);
    const [deliveryModalOrder, setDeliveryModalOrder] = useState<Order | null>(null);

    // Listen to real-time order changes within date range
    useEffect(() => {
        if (!isActive) return;
        setLoading(true);
        // Reset orders when date range changes to avoid mixing old/new queries visually before update
        setOrders([]);

        const unsubscribe = listenToOrderChangesByDateRange(
            new Date(endDate),
            {
                onAdd: (order) => setOrders(prev => {
                    if (prev.some(o => o.id === order.id)) return prev;
                    return [...prev, order].sort((a,b) => b.id - a.id);
                }),
                onChange: (order) => setOrders(prev => prev.map(o => o.id === order.id ? order : o).sort((a,b) => b.id - a.id)),
                onRemove: (order) => setOrders(prev => prev.filter(o => o.id !== order.id))
            },
            new Date(startDate)
        );

        // Short timeout to clear loading if no data comes immediately (Firebase is async)
        const loadingTimeout = setTimeout(() => setLoading(false), 500);
        return () => {
            clearTimeout(loadingTimeout);
            unsubscribe();
        };
    }, [isActive, startDate, endDate]);

