        setActiveMenuId(null);

        if (action === 'undo') {
            showAlert('완료 상태를 취소하시겠습니까?', async () => {
                await updateOrderStatus(order.id, null);
                showToast('완료 상태가 취소되었습니다.');
            });
        } else if (action === 'sms') {
            const text = exportToSMS(order);
            if (navigator.share) {
                navigator.share({ title: '발주서', text }).catch(() => {});
            } else {
                navigator.clipboard.writeText(text);
                showToast('발주 내용이 클립보드에 복사되었습니다.');
            }
            await updateOrderStatus(order.id, { type: 'sms', timestamp: new Date().toISOString() });
        } else if (action === 'xls') {
            setDeliveryModalOrder(order);
        } else if (action === 'pdf') {
            try {
                const { file } = await exportReturnToPDF(order);
                if (navigator.canShare && navigator.canShare({ files: [file] })) {
                    await navigator.share({
                        files: [file],
                        title: '반품서 PDF',
                    });
                } else {
                    const url = URL.createObjectURL(file);
                    window.open(url, '_blank');
                }
                await updateOrderStatus(order.id, { type: 'return', timestamp: new Date().toISOString() });
            } catch (e: any) {
                showAlert(e.message);
            }
        } else if (action === 'delete') {
            showAlert('정말 삭제하시겠습니까?\n이 작업은 되돌릴 수 없습니다.', async () => {
                await deleteOrder(order.id);
                showToast('삭제되었습니다.', 'success');
            }, '삭제', 'bg-red-600');
        }
    };

    const handleDeliveryConfirm = async (type: '일반배송' | '택배배송') => {
        if (!deliveryModalOrder) return;
        try {
            await exportToXLS(deliveryModalOrder, type);
            await updateOrderStatus(deliveryModalOrder.id, { type: 'xls', timestamp: new Date().toISOString() });
            showToast('엑셀 파일이 생성되었습니다.');
        } catch (e: any) {
            showAlert(e.message);
        } finally {
            setDeliveryModalOrder(null);
        }
    };

    return (
        <div className="flex flex-col h-full bg-gray-50" onClick={() => setActiveMenuId(null)}>
            {/* Header / Filter */}
            <div className="p-3 bg-white border-b border-gray-200 flex-shrink-0 space-y-2 z-20 shadow-sm">
                <div className="flex items-center gap-2">
                    <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="flex-1 h-10 px-2 border border-gray-300 rounded-lg text-sm font-bold text-gray-700 bg-white" />
                    <span className="text-gray-400">~</span>
                    <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="flex-1 h-10 px-2 border border-gray-300 rounded-lg text-sm font-bold text-gray-700 bg-white" />
                </div>
                <div className="relative">
                    <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                    <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="거래처명 검색" className="w-full h-10 pl-10 pr-4 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                </div>
            </div>

            {/* List */}
            <div className="flex-grow overflow-y-auto p-3 space-y-3">
                {loading && orders.length === 0 ? (
                    <div className="flex justify-center py-10"><SpinnerIcon className="w-8 h-8 text-blue-500 animate-spin" /></div>
                ) : filteredOrders.length === 0 ? (
                    <div className="text-center text-gray-400 py-10 font-medium">조회된 내역이 없습니다.</div>
                ) : (
                    filteredOrders.map(order => {
                        const isCompleted = !!order.completedAt;
                        const isMenuOpen = activeMenuId === order.id;

                        return (
                            <div key={order.id} onClick={() => openDetailModal(order)} className={`relative bg-white rounded-xl border shadow-sm active:bg-gray-50 transition-all ${isCompleted ? 'border-green-200 bg-green-50/30' : 'border-gray-200 hover:border-gray-300'}`}>
                                <div className="p-3">
                                    <div className="flex justify-between items-start mb-2">
                                        <div>
                                            <h3 className="font-bold text-gray-800 text-lg leading-tight">{order.customer.name}</h3>
                                            <p className="text-xs text-gray-500 mt-0.5 font-mono">{new Date(order.date).toLocaleString('ko-KR', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' })}</p>
                                        </div>
                                        {isCompleted ? (
                                            <div className="flex flex-col items-end">
                                                <span className="flex items-center gap-1 text-xs font-bold text-green-600 bg-green-100 px-2 py-1 rounded-full border border-green-200">
                                                    <CheckCircleIcon className="w-3.5 h-3.5" /> 완료
                                                </span>
                                                {order.completionDetails && (
                                                    <span className="text-[10px] text-gray-400 mt-1 font-medium">
                                                        {order.completionDetails.type === 'sms' ? 'SMS전송' : order.completionDetails.type === 'xls' ? '엑셀저장' : '반품서'}
                                                    </span>
