                                            </div>
                                        ) : (
                                            <span className="text-xs font-bold text-amber-600 bg-amber-100 px-2 py-1 rounded-full border border-amber-200">작성중</span>
                                        )}
                                    </div>
                                    <div className="flex justify-between items-end border-t border-dashed border-gray-100 pt-2 mt-2">
                                        <span className="text-xs font-medium text-gray-500">{order.itemCount} 품목</span>
                                        <span className="text-lg font-black text-gray-900 tabular-nums">{order.total.toLocaleString()} <span className="text-xs font-normal text-gray-500">원</span></span>
                                    </div>
                                </div>

                                <div className="absolute top-2 right-2">
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); setActiveMenuId(isMenuOpen ? null : order.id); }}
                                        className={`p-2 rounded-full transition-colors ${isMenuOpen ? 'bg-gray-100 text-gray-600' : 'text-gray-300 hover:text-gray-600'}`}
                                    >
                                        <MoreVerticalIcon className="w-5 h-5" />
                                    </button>

                                    {isMenuOpen && (
                                        <div className="absolute right-0 top-full mt-1 w-48 bg-white rounded-xl shadow-xl border border-gray-100 z-30 overflow-hidden animate-fade-in-down origin-top-right">
                                            {isCompleted ? (
                                                <button onClick={(e) => { e.stopPropagation(); handleMenuAction('undo', order); }} className="w-full text-left px-4 py-3 text-sm font-medium text-gray-700 flex items-center gap-3 hover:bg-gray-50 active:bg-gray-100">
                                                    <UndoIcon className="w-4 h-4 text-gray-400" /> 완료 취소
                                                </button>
                                            ) : (
                                                <>
                                                    <button onClick={(e) => { e.stopPropagation(); handleMenuAction('sms', order); }} className="w-full text-left px-4 py-3 text-sm font-medium text-gray-700 flex items-center gap-3 hover:bg-gray-50 active:bg-gray-100 border-b border-gray-50">
                                                        <SmsIcon className="w-4 h-4 text-green-500" /> SMS 내보내기
                                                    </button>
                                                    <button onClick={(e) => { e.stopPropagation(); handleMenuAction('xls', order); }} className="w-full text-left px-4 py-3 text-sm font-medium text-gray-700 flex items-center gap-3 hover:bg-gray-50 active:bg-gray-100 border-b border-gray-50">
                                                        <XlsIcon className="w-4 h-4 text-blue-500" /> XLS 내보내기
                                                    </button>
                                                    <button onClick={(e) => { e.stopPropagation(); handleMenuAction('pdf', order); }} className="w-full text-left px-4 py-3 text-sm font-medium text-gray-700 flex items-center gap-3 hover:bg-gray-50 active:bg-gray-100 border-b border-gray-50">
